scwin.vScrenID = "ULDSTF41111.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.BYCORP_CHRG_BZ_TP_CD = "", scwin.INVSTCOM_BZ_TP_CD = "", scwin.newYN = "";
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    //if (fr_bz_procs_no != "") 
    //{
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=ELW_ETF_COM_CONTACT_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwetf.comcontact.select.isurcd.Search" + "&{P}param01=" + scwin.BYCORP_CHRG_BZ_TP_CD + "&{P}param02=" + scwin.INVSTCOM_BZ_TP_CD + // 법인코드
        "&{P}param03=" + scwin.Isur_cd; // 시작일자

    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
    //}

};
scwin.fn_new_onload = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=ELW_ETF_COM_CONTACT_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwetf.comcontact.select.isurcd.new.dummy" + "&{P}param01=" + scwin.BYCORP_CHRG_BZ_TP_CD + "&{P}param02=" + scwin.INVSTCOM_BZ_TP_CD + // 법인코드
        "&{P}param03=" + scwin.Isur_cd; // 시작일자

    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_checkGubun = function() {
    if (gubun == '1') {
        txb_AfchgElwIsurNm.setReadOnly(false);
        txb_AfchgElwIsurEngNm.setReadOnly(false);
        txb_AfchgUlyNm.setReadOnly(true);
        txb_AfchgUlyEngNm.setReadOnly(true);
    } else if (gubun == '2') {
        txb_AfchgElwIsurNm.setReadOnly(true);
        txb_AfchgElwIsurEngNm.setReadOnly(true);
        txb_AfchgUlyNm.setReadOnly(false);
        txb_AfchgUlyEngNm.setReadOnly(false);
    }
};
scwin.fn_CheckForm = function() {
    if (!$c.stf.checkEmptyValue(txb_AFCHG_CHRG_NM, "변경후 담당자")) return false;
    if (!$c.stf.checkEmptyValue(txb_AFCHG_TEL_NO, "변경후 전화번호")) return false;
    if (!$c.stf.checkEmptyValue(txb_AFCHG_EMAIL, "변경 후 이메일")) return false;
    if (!$c.lce.fn_checkPhoneNumber($c.stf.getObjectValue(txb_AFCHG_TEL_NO))) {
        $c.win.alert("[전화번호 형식이 일치하지 않습니다.]");
        txb_AFCHG_TEL_NO.focus();
        return false;
    }
    if (!$c.stf.IsValidEmail(txb_AFCHG_EMAIL.getValue())) {
        $c.win.alert("[이메일 형식이 일치하지 않습니다.]");
        txb_AFCHG_EMAIL.focus();
        return false;
    }
    return true;
};
scwin.fn_save_trs = function() {
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lce.fn_encodeNSession("/ELWUnderlyingAsset.do?method=saveELWETFIsurCd&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I:pInput=dts_Mst)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx;
    trs.Post();
};


