scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        //fr_bz_procs_no = fn_getNewBzProcNo( dts_BzProcsNo );

        //if (fr_bz_procs_no.length != 14) {
        //	alert(getMessageParam("MSG-0010", ""));
        //} else {

        scwin.trsIdx = TRS_IDX_INSERT;

        //dts_Mst.NameString(dts_Mst.RowPosition, "BZ_PROCS_NO") = fr_bz_procs_no;
        //dts_Mst.NameString(dts_Mst.RowPosition, "ISUR_CD") = Isur_cd;

        //fn_SetValue() ;
        scwin.fn_save_trs();
        //}

    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};


//function fn_drft() { }
//function fn_makt() { }

scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');

    //if (buttonSet.status == "D") { // 삭제처리의 응답인 경우
    //	frame.CloseFrame();
    //} 
    //else {
    //	fn_search();
    //}	
    await $c.frame.CloseFrame();
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.newYN == "Y") {
        buttonSet.setInsertStatus();
    } else {
        buttonSet.setUpdateStatus();
        //	setButtonSetWithDate( edt_MktactEnforceDd , false ) ;

    }
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.BYCORP_CHRG_BZ_TP_CD = (arrPar.length >= 5 ? arrPar[4] : ""); // elw/etn/etf 구분
        scwin.INVSTCOM_BZ_TP_CD = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/LP 구분값
        scwin.newYN = (arrPar.length >= 7 ? arrPar[6] : ""); //  신규여부

    }

    //fn_checkGubun() ;
    txb_ISUR_NM.setValue(scwin.Isur_nm);
    if (scwin.INVSTCOM_BZ_TP_CD == "1") txb_INVSTCOM_BZ_TP_CD.setValue("발행사");

    else if (scwin.INVSTCOM_BZ_TP_CD == "2") txb_INVSTCOM_BZ_TP_CD.setValue("유동성공급사");

    else if (scwin.INVSTCOM_BZ_TP_CD == "3") txb_INVSTCOM_BZ_TP_CD.setValue("운용사");
    if (scwin.BYCORP_CHRG_BZ_TP_CD == "3") txb_BYCORP_CHRG_BZ_TP_CD.setValue("ELW");

    else if (scwin.BYCORP_CHRG_BZ_TP_CD == "6") txb_BYCORP_CHRG_BZ_TP_CD.setValue("ETN");

    else if (scwin.BYCORP_CHRG_BZ_TP_CD == "5") txb_BYCORP_CHRG_BZ_TP_CD.setValue("ETF");

    else if (scwin.BYCORP_CHRG_BZ_TP_CD == "7") txb_BYCORP_CHRG_BZ_TP_CD.setValue("상장형 수익증권");

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    if (scwin.newYN == "Y") {
        scwin.fn_new_onload(); // 신규작성시 호출

    } else {
        scwin.fn_search();
    }
    $c.cm.PanelToGroupBox(panel_3);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
